<script lang="ts">
 import { planBlend } from '@vinea/domain';
 import { forms,label } from '$lib/forms';import { translator } from '$lib/app-i18n';import type { Language } from '$lib/i18n';import { invalidateAll } from '$app/navigation';import { saveDraft } from '$lib/offline';
 let {type,model,lang,tenantId,expanded=false,defaults={},onDirty=()=>{},onSaved=()=>{}}:{type:string;model:Record<string,Record<string,any>[]>;lang:Language;tenantId:string;expanded?:boolean;defaults?:Record<string,string>;onDirty?:()=>void;onSaved?:()=>void}=$props();
 let t=$derived(translator(lang));let fields=$derived(forms[type]);let volumes=$state<Record<string,string>>({});
 let preview=$derived.by(()=>{if(!['recipe_save','mix'].includes(type))return null;try{return planBlend(model.positions.map(p=>{const lot=model.lots.find(l=>l.id===p.lot_id);const superseded=new Set(model.analyses.map(a=>a.supersedes).filter(Boolean));const analysis=model.analyses.find(a=>a.lot_id===p.lot_id&&a.parameter==='alcohol'&&a.quality==='measured'&&!superseded.has(a.id));return {id:p.id,volume:volumes[p.id]||'0',available:p.available_l,cost:lot?.cost_per_l??'0',alcohol:analysis?.value??null,unit:analysis?.unit??null,method:analysis?.method??null,blocked:p.blocked};}));}catch{return null;}});let errors=$state<Record<string,boolean>>({});const decimalField=(key:string)=>/(?:_l|_ha|_kg|_ml)$/.test(key)||['amount','value','cost_per_unit','quantity','hours','reorder_at','minimum','maximum','target_temperature','sugar','acidity','ph'].includes(key);let message=$state(''),busy=$state(false),retryKey=$state('');
 async function submit(event:SubmitEvent){event.preventDefault();if(busy)return;const form=event.currentTarget as HTMLFormElement;const data=new FormData(form);const command:Record<string,any>={type};
  for(const field of fields){if(field.type==='sources'||field.type==='components'){command[field.key]=model.positions.filter(p=>Number(data.get('source_'+p.id))>0).map(p=>({position_id:p.id,quantity_l:String(data.get('source_'+p.id)),...(field.type==='sources'?{expected_version:p.version}:{})}));continue;}
   if(field.type==='materials'){command.requirements=(model.materials??[]).filter(m=>Number(data.get('material_'+m.id))>0).map(m=>({material_id:m.id,per_bottle:String(data.get('material_'+m.id)),batch:String(data.get('batch_'+m.id)??'')}));continue;}
   if(field.type==='checklist'||field.type==='completed_checklist'){command.checklist=String(data.get(field.key)??'').split('\n').map(s=>s.trim()).filter(Boolean).map(label=>({label,done:field.type==='completed_checklist'&&data.has('checklist_complete')}));continue;}
   if(field.type==='multiselect'){command[field.key]=data.getAll(field.key);continue;}
   if(field.type==='checkbox'){command[field.key]=data.has(field.key);continue;}
   let value=data.get(field.key)?.toString()??'';if(decimalField(field.key))value=value.replace(',','.');if(!value&&field.optional)continue;command[field.key]=field.key==='assignee_id'?value:field.type==='number'?Number(value):field.type==='datetime'?new Date(value).toISOString():value;
  }
  for(const [key,collection] of [['field_id','field_operations'],['material_id','materials'],['resource_id','resources'],['run_id','fermentations'],['maintenance_id','maintenance'],['sensor_id','sensors'],['plan_id',type.startsWith('harvest_plan')?'harvest_plans':'bottling_plans'],['vessel_id','vessels'],['position_id','positions'],['lot_id','lots'],['recipe_id','recipes'],['task_id','tasks'],['order_id','orders']]){if(command[key]&&['vessel_update','transfer','split','loss','adjustment','bottle','reserve','lot_block','recipe_freeze','approve','task_update','approve_deviation','produce','field_approve','material_receive','treatment_record','cleaning_record','fermentation_update','maintenance_update','harvest_plan_update','bottling_plan_cancel','bottling_execute','sensor_disable'].includes(type)){const row=model[collection].find(r=>r.id===command[key]);if(row)command[type==='produce'&&key==='order_id'?'order_version':'expected_version']=row.version;}}
  if(type==='produce')delete command.expected_version;
  if(type==='bottling_execute'){const plan=model.bottling_plans.find(p=>p.id===command.plan_id);command.position_version=model.positions.find(p=>p.id===plan?.position_id)?.version;}
  busy=true;message='';errors={};const key=retryKey||crypto.randomUUID();
  try{if(!navigator.onLine){await saveDraft(tenantId,command,key);retryKey='';onSaved();form.reset();volumes={};message=t('draftSaved');return;}
   const res=await fetch('/api/commands',{method:'POST',headers:{'content-type':'application/json','idempotency-key':key},body:JSON.stringify(command)});
   const result=await res.json();if(!res.ok){retryKey='';for(const issue of result.issues??[])errors[String(issue.path?.[0]??'')]=true;message=result.message==='MFA_REQUIRED'?t('mfaRequired'):result.message==='VERSION_CONFLICT'?t('conflict'):result.message?t(result.message):t('INVALID_INPUT');return;}
   retryKey='';message=t('saved');form.reset();volumes={};onSaved();await invalidateAll();
  }catch(cause){retryKey=key;message=cause instanceof Error?cause.message:'Connection failed';}finally{busy=false;}
 }
</script>
<details class="command" open={expanded}><summary>{t(type)}</summary><form onsubmit={submit} oninput={onDirty}><div class="fields">{#each fields as field}<fieldset class:wide={field.type==='textarea'||field.type==='components'||field.type==='sources'}><legend>{field.key==='ph'?'pH':t(field.key==='user_id'?'uxTeamMember':field.key)} <small>{field.optional?t('uxOptional'):field.type==='checkbox'?'':'*'}</small></legend>{#if field.type==='select'}<select name={field.key} aria-label={field.key==='ph'?'pH':t(field.key==='user_id'?'uxTeamMember':field.key)} aria-invalid={!!errors[field.key]} value={defaults[field.key]??''} required={!field.optional}><option value="">—</option>{#if field.options}{#each field.options as option}<option value={option}>{t(option==='bottle'&&type==='material_create'?'bottle_item':option)}</option>{/each}{:else}{#each model[field.collection??'']??[] as row}<option value={field.key==='correction_of'&&field.collection==='ledger'?row.operation_id:['assignee_id','user_id'].includes(field.key)?row.user_id:row.id}>{label(row,field.collection??'')}</option>{/each}{/if}</select>{:else if field.type==='multiselect'}<select name={field.key} aria-label={field.key==='ph'?'pH':t(field.key==='user_id'?'uxTeamMember':field.key)} aria-invalid={!!errors[field.key]} multiple size="4">{#each model[field.collection??'']??[] as row}<option value={row.id}>{label(row,field.collection??'')}</option>{/each}</select>{:else if field.type==='sources'||field.type==='components'}<div class="sources">{#each model.positions.filter(p=>Number(p.quantity_l)>0) as p}<label><span>{label(p,'positions')}</span><input name={'source_'+p.id} oninput={(e)=>volumes[p.id]=e.currentTarget.value} inputmode="decimal" type="number" min="0" step="0.001" placeholder="0" /></label>{/each}</div>{:else if field.type==='materials'}<div class="sources">{#each model.materials??[] as m}<div class="material-input"><label><span>{m.code} · {m.name} · {t(m.unit)} / {t('bottle_count')}</span><input aria-label={m.code+' · '+t('quantity')} name={'material_'+m.id} type="number" min="0" step="0.001" placeholder="0" /></label><label>{t('batch')}<input aria-label={m.code+' · '+t('batch')} name={'batch_'+m.id} placeholder={t('batch')} /></label></div>{/each}</div>{:else if field.type==='checklist'||field.type==='completed_checklist'}<textarea name={field.key} aria-label={field.key==='ph'?'pH':t(field.key==='user_id'?'uxTeamMember':field.key)} aria-invalid={!!errors[field.key]} rows="3" maxlength="5000" placeholder={t('onePerLine')}></textarea>{#if field.type==='completed_checklist'}<label class="check"><input type="checkbox" name="checklist_complete" /> {t('checklist_complete')}</label>{/if}{:else if field.type==='textarea'}<textarea name={field.key} aria-label={field.key==='ph'?'pH':t(field.key==='user_id'?'uxTeamMember':field.key)} aria-invalid={!!errors[field.key]} value={defaults[field.key]??''} required={!field.optional} maxlength="5000" rows="3"></textarea>{:else if field.type==='checkbox'}<input type="checkbox" name={field.key} aria-label={field.key==='ph'?'pH':t(field.key==='user_id'?'uxTeamMember':field.key)} aria-invalid={!!errors[field.key]} />{:else}<input name={field.key} aria-label={field.key==='ph'?'pH':t(field.key==='user_id'?'uxTeamMember':field.key)} aria-invalid={!!errors[field.key]} type={field.type==='datetime'?'datetime-local':field.type==='number'?'number':'text'} value={defaults[field.key]??(field.type==='datetime'?(field.optional?'':new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16)):field.value??'')} min={field.min} max={field.max} required={!field.optional} maxlength="2000" inputmode={decimalField(field.key)?'decimal':undefined} />{/if}{#if errors[field.key]}<p class="field-error">{t('uxCheckField')}</p>{/if}</fieldset>{/each}</div>{#if preview}<div class="preview"><strong>{preview.volume} L · {preview.costPerLiter} €/L</strong><p>{t('alcohol')} · {preview.alcohol??t('missing')} {preview.alcohol?'% vol':''}</p><p>{t('ph')}</p></div>{/if}<button disabled={busy}>{busy?t('saving'):t(type)}</button>{#if message}<p role="status" class="message notice">{message}</p>{/if}</form></details>
<style>.command{border:1px solid #dfe5da;border-radius:9px;background:white;margin:10px 0}.command summary{padding:16px 18px;cursor:pointer;font-weight:500;font-size:14px}.command[open] summary{border-bottom:1px solid #eef0e9}form{padding:22px}.fields fieldset{border:0;padding:0;margin:0;min-width:0;display:grid;gap:7px;align-content:start}.fields legend{font-size:13px;font-weight:550;color:#405950;margin-bottom:7px}.fields .check{display:flex;align-items:center;gap:8px;font-size:12px}.field-error{font-size:11px;color:var(--danger);margin:0}[aria-invalid=true]{border-color:var(--danger)}.fields small{color:var(--muted);font-weight:400;font-size:10px}.command[open]{border-color:#bfd6c8}.command[open] summary{background:#f7fbf8}.fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:16px;margin-bottom:20px}.wide{grid-column:1/-1}.sources{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:10px;background:#f8faf5;border-radius:7px;padding:12px}.sources label{font-size:11px}.material-input{display:grid;gap:10px}input[type=checkbox]{width:18px;height:18px}.message{font-size:12px;overflow-wrap:anywhere}</style>
